import gurobipy as gp
from gurobipy import GRB
foods = []
calories = {}
protein = {}
fat = {}
vitaminc = {}
cost = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    food = v['Food']
    foods.append(food)
    try:
        calories[food] = float(v['Calories'])
        protein[food] = float(v['Protein(g)'])
        fat[food] = float(v['Fat(g)'])
        vitaminc[food] = float(v['VitaminC(mg)'])
        cost[food] = float(v['Cost'])
    except KeyError as e:
        raise ValueError(f'Missing field {e} in record for food {food}')
for food in foods:
    for d, dct in [('Calories', calories), ('Protein', protein), ('Fat', fat), ('VitaminC', vitaminc), ('Cost', cost)]:
        if food not in dct:
            raise ValueError(f'Missing {d} for food {food}')
m = gp.Model('meal_plan')
x = m.addVars(foods, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((cost[f] * x[f] for f in foods)), GRB.MINIMIZE)
m.addConstr(gp.quicksum((calories[f] * x[f] for f in foods)) >= 2000, name='calories')
m.addConstr(gp.quicksum((protein[f] * x[f] for f in foods)) >= 50, name='protein')
m.addConstr(gp.quicksum((vitaminc[f] * x[f] for f in foods)) >= 60, name='vitaminc')
m.addConstr(gp.quicksum((fat[f] * x[f] for f in foods)) <= 70, name='fat')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')